const discordIdToClickup = global.get('discordIdToClickup') || {};

const comment = msg.comment;
const discordMentionRegex = /(<@\d+>)/;
const splittedComment = comment.split(discordMentionRegex).filter(Boolean);

const formattedMentions = splittedComment.map(part => {
    if (discordMentionRegex.test(part)) {
        const discordId = part.split('<@')[1].split('>')[0];
        return {"type": "tag","user":{"id": discordIdToClickup[discordId].clickupId}};
    }
    return {"text": `${part}`};
});

msg.payload = formattedMentions;

return msg;

const comment = msg.payload;

const splittedBoldItalic = comment.map(part => {
    if (part.hasOwnProperty("text")) {
        return part.text.split("***");
    }
    return part;
});

let formattedBoldItalic = splittedBoldItalic.map(part => {
    if (Array.isArray(part)) {
        return part.map((substr, i) => {
            if (i % 2 !== 0) {
                return {"text": substr, "attributes": { italic: true, bold: true }};
            }
            return {text: substr, attributes: {}};
        });
    }
    return part;
});

formattedBoldItalic = formattedBoldItalic.map(item => {
    if (Array.isArray(item)){
        return item.filter(obj => obj.text !== "");
    }
    return item;
});

const formattedComment = [];

formattedBoldItalic.forEach(part => {
    if (Array.isArray(part)) {
        part.forEach(substr => formattedComment.push(substr));
    } else {
        formattedComment.push(part);
    }
});

msg.payload = formattedComment.filter(item => item !== undefined);

return msg;

