const splittedItalic = comment.map(part => {
    if (part.hasOwnProperty("text") && Object.keys(part.attributes).length === 0) {
        const split = part.text.split("*");
        const result = [];
        split.forEach(item => {
            result.push({text: item, attributes: {...part.attributes}});
        })
        return result;
    }
    return part;
});

