const boundary = '----FORMDATA';

const createFileRequest = (
    data,
    boundary
) => {
    const header = (
        `--${boundary}\r\n`
        + `Content-Disposition: form-data; name="attachment"; filename="${msg.attachment.name}"`
        + '\r\n'
        + `Content-Type: application/octet-stream`
        + '\r\n\r\n'
    );
    return Buffer.concat([
        Buffer.from(header, 'utf-8'),
        data,
        Buffer.from('\r\n', 'utf-8'),
    ]);
};

const buildRequestOptions = (boundary, length) => (
    {
        method: 'POST',
        hostname: 'api.clickup.com',
        path: `/api/v2/task/${msg.taskId}/attachment?custom_task_ids=true&team_id=${global.get("clickUpSettings.general.teamId")}`,
        headers: {
            'Content-Type': `multipart/form-data; boundary=${boundary}`,
            'Content-Length': length,
            Accept: '*/*',
            Authorization: msg.clickupToken
        },
    }
);

const uploadRequest = createFileRequest(msg.payload, boundary);

const footer = `--${boundary}--`;

const body = Buffer.concat([
    uploadRequest,
    Buffer.from(footer, 'utf-8'),
]);

const options = buildRequestOptions(boundary, body.length);

const req = https.request(options, (res) => {
    console.log(`status: ${res.statusCode}`);

    res.on('data', (chunk) => {
        // node.warn(`BODY: ${chunk}`);
    });

    res.on('end', () => {
        node.send(msg);
    });
});

req.on('error', (e) => {
    node.error(`Problem with request: ${e.message}`);
});

req.write(body);

req.end();

